<template>
  <main class="page"><section class="wrap"><header class="hero glass"><div><span>GROUP DECISIONS</span><h1>Purchase proposals</h1><p>Members decide together. Voting does not spend the wallet; only an authorised Stokvel officer can release group funds.</p></div><div class="wallet"><small>GROUP WALLET</small><strong>R {{ money(walletBalance) }}</strong></div></header><div v-if="error" class="message">{{ error }}</div><div v-if="loading" class="state glass">Loading proposals...</div><div v-else-if="!proposals.length" class="empty glass"><h2>No proposals yet</h2><p>Build a basket from the catalogue and submit it for a group vote.</p><RouterLink class="button" to="/catalogue">Browse catalogue</RouterLink></div><section v-else class="list"><article v-for="proposal in proposals" :key="proposal.proposal_id" class="proposal glass"><div class="proposal-head"><div><span class="status">{{ proposal.status }}</span><h2>{{ proposal.title }}</h2><p>{{ proposal.description }}</p><small>Created by {{ proposal.created_by_name }}</small></div><strong class="total">R {{ money(proposal.items.reduce((sum,item)=>sum+Number(item.subtotal||0),0)) }}</strong></div><div class="delivery-summary"><span>{{ proposal.delivery_mode==='INDIVIDUAL' ? 'INDIVIDUAL MEMBER DELIVERY' : 'GROUP DELIVERY' }}</span><strong>{{ proposal.delivery_mode==='INDIVIDUAL' ? 'Each member receives their share at their default address.' : (proposal.delivery_address || 'Group address to be confirmed') }}</strong></div><div class="items"><div v-for="item in proposal.items" :key="item.proposal_item_id"><b>{{ item.product_name }}</b><span>{{ item.quantity }} × {{ money(item.unit_price) }} · {{ item.supplier_name }}</span></div></div><div class="votes"><span>✓ {{ proposal.approve_votes }} approve</span><span>✕ {{ proposal.reject_votes }} reject</span><span v-if="proposal.my_vote">Your vote: {{ proposal.my_vote }}</span></div><div v-if="proposal.status==='VOTING'" class="actions"><button class="approve" @click="vote(proposal.proposal_id,'APPROVE')">Approve</button><button class="reject" @click="vote(proposal.proposal_id,'REJECT')">Reject</button></div><div v-if="isOfficer && proposal.status==='VOTING'" class="officer"><button class="button" @click="approve(proposal.proposal_id)">Approve after majority</button></div><div v-if="isOfficer && proposal.status==='APPROVED'" class="officer"><button class="button" @click="authorise(proposal.proposal_id)">Authorise & spend wallet</button></div><div v-if="proposal.status==='ORDERED'" class="ordered">Order #{{ proposal.order_id }} has been authorised and funded from the group wallet.</div></article></section></section></main>
</template>
<script setup>
import { computed,onMounted,ref } from 'vue';
import { getStokvelProposals,voteOnProposal,approvePurchaseProposal,authorisePurchaseProposal } from '../services/api.js';
const loading=ref(true),error=ref(''),proposals=ref([]),walletBalance=ref(0),membership=ref(null);const isOfficer=computed(()=>['CHAIRPERSON','TREASURER'].includes(String(membership.value?.stokvel_role||'').toUpperCase()));const money=v=>Number(v||0).toLocaleString('en-ZA',{minimumFractionDigits:2,maximumFractionDigits:2});
async function load(){loading.value=true;error.value='';try{const r=await getStokvelProposals();proposals.value=r.proposals||[];walletBalance.value=Number(r.wallet_balance||0);membership.value=r.membership||null}catch(e){error.value=e.response?.data?.message||'Unable to load proposals.'}finally{loading.value=false}}
async function action(fn){try{await fn();await load()}catch(e){error.value=e.response?.data?.message||'The proposal action failed.'}}
function vote(id,v){return action(()=>voteOnProposal(id,v))}function approve(id){return action(()=>approvePurchaseProposal(id))}function authorise(id){return action(()=>authorisePurchaseProposal(id))}onMounted(load);
</script>
<style scoped>
.page{min-height:100vh;background:var(--sw-page-background);color:var(--sw-page-text);padding:40px 20px 80px}.wrap{max-width:1100px;margin:auto}.glass{background:var(--sw-glass-light);border:1px solid var(--sw-glass-light-border);box-shadow:var(--sw-glass-shadow-light);backdrop-filter:blur(var(--sw-glass-blur));border-radius:22px}.hero{padding:38px;display:flex;justify-content:space-between;gap:25px;align-items:center;background:var(--sw-page-gradient)}.hero>div>span,.status{font:800 10px var(--sw-font-body);letter-spacing:.14em;color:var(--sw-gold-500)}h1{font:800 clamp(42px,7vw,70px)/.95 var(--sw-font-heading);margin:14px 0}.hero p,.proposal p,.empty p{color:var(--sw-page-text-soft);line-height:1.6}.wallet{min-width:180px;padding:25px;border:1px solid var(--sw-gold-500);border-radius:18px}.wallet small{display:block;color:var(--sw-page-text-soft);font-size:9px}.wallet strong{display:block;margin-top:8px;color:var(--sw-gold-500);font:800 24px var(--sw-font-heading)}.message,.state{margin-top:18px;padding:16px;border-radius:14px}.message{border:1px solid rgba(210,75,55,.3);color:#b42318}.state{text-align:center}.empty{margin-top:18px;padding:55px;text-align:center}.button{display:inline-block;margin-top:14px;padding:12px 18px;border:0;border-radius:10px;background:var(--sw-gold-500);color:var(--sw-purple-900);font-weight:800;text-decoration:none;cursor:pointer}.list{display:grid;gap:16px;margin-top:18px}.proposal{padding:25px}.proposal-head{display:flex;justify-content:space-between;gap:20px}.proposal h2{margin:8px 0;font:800 26px var(--sw-font-heading)}.proposal small{color:var(--sw-page-text-soft)}.total{font:800 24px var(--sw-font-heading);white-space:nowrap}.delivery-summary{display:grid;gap:5px;margin-top:18px;padding:14px 15px;border:1px solid var(--sw-input-border);border-radius:14px;background:var(--sw-page-background)}.delivery-summary span{font:800 9px var(--sw-font-body);letter-spacing:.1em;color:var(--sw-purple-700)}.delivery-summary strong{font:700 11px/1.5 var(--sw-font-body);color:var(--sw-page-text-soft)}.items{display:grid;gap:8px;margin-top:12px;padding:15px;border-radius:14px;background:var(--sw-page-background)}.items div{display:flex;justify-content:space-between;gap:15px;border-bottom:1px solid var(--sw-input-border);padding:8px 0}.items div:last-child{border:0}.items span,.votes{color:var(--sw-page-text-soft);font-size:11px}.votes{display:flex;gap:18px;flex-wrap:wrap;margin-top:15px}.actions,.officer{display:flex;gap:10px;margin-top:18px}.actions button{padding:11px 17px;border-radius:10px;font-weight:800;cursor:pointer}.approve{border:0;background:var(--sw-gold-500);color:var(--sw-purple-900)}.reject{border:1px solid #b42318;background:transparent;color:#b42318}.officer .button{margin:0}.ordered{margin-top:18px;padding:13px;border-radius:10px;background:rgba(55,170,105,.1);color:#247747;font-size:11px}@media(max-width:650px){.hero,.proposal-head{flex-direction:column;align-items:flex-start}.wallet{width:100%;box-sizing:border-box}.items div{flex-direction:column;gap:4px}}
</style>
